def main():
 RUN.mkdir(parents=True,exist_ok=True)
 if (RUN/'cases.json').exists():raise RuntimeError('Cases are frozen; do not replace after retrieval')
 inventory=json.loads((BASE/'performance-inventory.json').read_text(encoding='utf-8'));items={r['id']:r for r in inventory};cases=[];errors=[];counts=collections.Counter()
 cache={k:[page.get_text() for page in pymupdf.open(BASE/r['path'])] for k,r in items.items()}
 for key,question,atoms,kind in DEFS:
  item=items[key];texts=cache[key];pages=[i+1 for i,t in enumerate(texts) if all(sc.norm(a) in sc.norm(t) for a in atoms)]
  if not pages:
   missing=[a for a in atoms if not any(sc.norm(a) in sc.norm(t) for t in texts)];errors.append({'document':key,'question':question,'atoms':atoms,'missing_in_entire_source':missing});continue
  counts[key]+=1;cases.append({'case_id':key+'-q'+str(counts[key]),'document_key':key,'title':item['title'],'language':item['language'],'group':item['group'],'kind':kind,'question':question,'units':[{'pages':pages,'atoms':atoms}],'source_sha256':item['sha256'],'label_status':'SOURCE_ALIGNED_PENDING_HUMAN_REVIEW','reference_text':texts[pages[0]-1]})
 (RUN/'source-validation-errors.json').write_text(json.dumps(errors,ensure_ascii=False,indent=2),encoding='utf-8')
 if errors:print(json.dumps(errors,ensure_ascii=True,indent=2));raise SystemExit(1)
 assert len(cases)==90 and len(counts)==30 and set(counts.values())=={3}
 data=json.dumps(cases,ensure_ascii=False,indent=2).encode();(RUN/'cases.json').write_bytes(data)
 (RUN/'freeze.json').write_text(json.dumps({'cases':90,'documents':30,'questions_per_document':3,'language_counts':dict(collections.Counter(c['language'] for c in cases)),'sha256':hashlib.sha256(data).hexdigest(),'labels_fixed_before_retrieval':True,'chat_llm':False},indent=2),encoding='utf-8')
 print('Frozen 90 source-aligned natural questions, 3 per PDF, 45 per language.')
if __name__=='__main__':main()
